<!-- @FIGURE_UI_BEGIN -->
<label>Side length a: <output id="sideAVal">4</output>
<input id="sideAInput" type="range" min="3" max="12" step="0.1" value="4" oninput="document.getElementById('sideAVal').value=this.value;update_sideA(+this.value)"></label>
<label><input id="showAltitudeInput" type="checkbox" checked onchange="toggle_showAltitude(this.checked)"> Show altitude h</label>
