// @FIGURE_CODE_BEGIN
(function(){
var W=1200,H=750;
var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0,0,W,H);

var ALPHA=Math.PI/6; // 30 degrees
var B=10, H_ALT=B*Math.sin(ALPHA); // h=5
var cosA=Math.cos(ALPHA), sinA=Math.sin(ALPHA);

// Panel geometry
var panelScale=13;
var panelBaseY=265;
var panelXs=[30,320,610,900];
var panelHeadings=['No triangle, a < h','Right triangle, a = h','Two triangles, a > h, a < b','One triangle, a ≥ b'];
var panelTags=['(a)','(b)','(c)','(d)'];
var panelA=[4,5,7,11];

// Live area geometry
var liveScale=18;
var liveBaseY=660;
var liveAlphaX=100;
var liveGammaX=liveAlphaX+B*liveScale*cosA;
var liveGammaY=liveBaseY-B*liveScale*sinA;

// Colors
var colBlack='#222';
var colBlue='#2266cc';
var colRed='#cc2222';
var colHighlight='rgba(200,230,255,0.35)';

// Helper: text with halo
function haloText(parent,x,y,str,size,anchor,color){
  return parent.text(str).attr({x:x,y:y,'font-size':size||14,'text-anchor':anchor||'middle',fill:color||colBlack,'paint-order':'stroke',stroke:'#fff','stroke-width':3,'stroke-linejoin':'round','font-family':'serif'});
}

// Draw angle arc at vertex
function drawAngleArc(parent,vx,vy,radius,startAngle,endAngle){
  var pts=[];
  for(var i=0;i<=20;i++){
    var t=startAngle+(endAngle-startAngle)*i/20;
    pts.push([vx+radius*Math.cos(t),vy-radius*Math.sin(t)]);
  }
  return parent.polyline(pts.map(function(p){return p[0]+','+p[1]}).join(' ')).fill('none').stroke({color:colBlack,width:1.2});
}

// Draw right angle square
function drawRightAngle(parent,x,y,size){
  return parent.polyline((x-size)+','+y+' '+(x-size)+','+(y-size)+' '+x+','+(y-size)).fill('none').stroke({color:colBlue,width:1.5});
}

// ── Static panels ──
var panelGroups=[];
var panelHighlights=[];

for(var p=0;p<4;p++){
  var px=panelXs[p];
  var g=draw.group();
  panelGroups.push(g);

  // Highlight rect (initially hidden)
  var hl=g.rect(270,280).attr({x:px-10,y:45,fill:colHighlight,opacity:0,rx:6});
  panelHighlights.push(hl);

  // Heading
  haloText(g,px+130,35,panelHeadings[p],13,'middle');

  // Tag
  haloText(g,px+130,295,panelTags[p],14,'middle');

  var ax=px+15, ay=panelBaseY;
  var gx=ax+B*panelScale*cosA, gy=ay-B*panelScale*sinA;
  var footX=gx, footY=ay;
  var aLen=panelA[p]*panelScale;

  // Base line
  var baseEnd=ax+B*panelScale*cosA+ (p===3? 120: 60);
  if(p===3) baseEnd=ax+18.5*panelScale; // for a=11, x2≈18.46
  if(p===2) baseEnd=ax+14*panelScale;
  g.line(ax,ay,baseEnd,ay).stroke({color:colBlack,width:1.5});

  // Side b from α to γ
  g.line(ax,ay,gx,gy).stroke({color:colBlack,width:1.8});
  haloText(g,(ax+gx)/2-12,(ay+gy)/2,'b',14,'middle');

  // Angle arc at α
  drawAngleArc(g,ax,ay,22,0,ALPHA);

  // Vertex labels
  haloText(g,ax-12,ay+5,'α',14,'middle');
  haloText(g,gx,gy-12,'γ',14,'middle');

  if(p===0){
    // No triangle: a hangs from γ but doesn't reach base
    var aEndY=gy+aLen;
    g.line(gx,gy,gx,aEndY).stroke({color:colRed,width:1.8});
    haloText(g,gx+14,(gy+aEndY)/2,'a',14,'middle',colRed);
    haloText(g,baseEnd+10,ay+5,'β',14,'middle');
  } else if(p===1){
    // Right triangle: a reaches base at foot (β = foot)
    g.line(gx,gy,gx,ay).stroke({color:colRed,width:1.8});
    haloText(g,gx+14,(gy+ay)/2,'a',14,'middle',colRed);
    drawRightAngle(g,gx,ay,10);
    haloText(g,gx+8,ay+16,'β',14,'middle');
  } else if(p===2){
    // Two triangles: altitude h + two dashed a segments
    // Altitude
    g.line(gx,gy,gx,ay).stroke({color:colBlue,width:1.5});
    haloText(g,gx+12,(gy+ay)/2+10,'h',13,'middle',colBlue);
    // Two intersection points
    var d=Math.sqrt(panelA[p]*panelA[p]-H_ALT*H_ALT)*panelScale;
    var x1=gx-d, x2=gx+d;
    g.line(gx,gy,x1,ay).stroke({color:colRed,width:1.5,dasharray:'6,4'});
    g.line(gx,gy,x2,ay).stroke({color:colRed,width:1.5,dasharray:'6,4'});
    haloText(g,(gx+x1)/2-10,(gy+ay)/2,'a',13,'middle',colRed);
    haloText(g,(gx+x2)/2+12,(gy+ay)/2,'a',13,'middle',colRed);
    haloText(g,x2+10,ay+5,'β',14,'middle');
  } else {
    // One triangle: a slopes from γ to β
    var d2=Math.sqrt(panelA[p]*panelA[p]-H_ALT*H_ALT)*panelScale;
    var bx2=gx+d2;
    g.line(gx,gy,bx2,ay).stroke({color:colRed,width:1.8});
    haloText(g,(gx+bx2)/2+14,(gy+ay)/2,'a',14,'middle',colRed);
    haloText(g,bx2+10,ay+5,'β',14,'middle');
  }
}

// ── Live construction area ──
var liveG=draw.group();
var liveHeading=haloText(liveG,400,340,'Live SSA Construction',15,'middle');

// Fixed elements
var lax=liveAlphaX, lay=liveBaseY;
var lgx=liveGammaX, lgy=liveGammaY;
var lfootX=lgx, lfootY=lay;

// Base ray
var baseRay=liveG.line(lax,lay,lax+25*liveScale,lay).stroke({color:colBlack,width:1.5});

// Side b
liveG.line(lax,lay,lgx,lgy).stroke({color:colBlack,width:2});
haloText(liveG,(lax+lgx)/2-16,(lay+lgy)/2,'b',15,'middle');

// Angle arc at α
drawAngleArc(liveG,lax,lay,28,0,ALPHA);

// Vertex labels
haloText(liveG,lax-14,lay+6,'α',15,'middle');
haloText(liveG,lgx,lgy-14,'γ',15,'middle');

// Altitude group (toggleable)
var altGroup=liveG.group();
var altLine=altGroup.line(lgx,lgy,lgx,lay).stroke({color:colBlue,width:1.5,dasharray:'4,3'});
var altLabel=haloText(altGroup,lgx+14,(lgy+lay)/2,'h',14,'middle',colBlue);
var altFootDot=altGroup.circle(5).attr({cx:lgx,cy:lay,fill:colBlue});

// Swinging arc and side a
var arcGroup=liveG.group();
var sideALine=arcGroup.line(lgx,lgy,lgx,lgy).stroke({color:colRed,width:2});
var arcPath=arcGroup.path('').fill('none').stroke({color:colRed,width:1,dasharray:'3,3',opacity:0.5});
var dot1=arcGroup.circle(8).attr({fill:colRed,opacity:0});
var dot2=arcGroup.circle(8).attr({fill:colRed,opacity:0});
var betaLabel=haloText(arcGroup,0,0,'β',15,'middle');

// Case readout
var caseText=haloText(liveG,700,380,'',14,'middle');
var ineqText=haloText(liveG,700,400,'',12,'middle');

// Current side a label
var sideALabel=haloText(arcGroup,0,0,'a',14,'middle',colRed);

var currentA=4;
var showAlt=true;
var currentCaseIdx=0;
var caseNames=['No triangle','Right triangle','Two triangles','One triangle'];

function getCase(a){
  if(a<H_ALT-0.01) return 0;
  if(Math.abs(a-H_ALT)<0.05) return 1;
  if(a<H_ALT+0.05) return 1;
  if(a<B-0.01) return 2;
  return 3;
}

function updateLive(){
  var a=currentA;
  var aPx=a*liveScale;
  var hPx=H_ALT*liveScale;
  var caseIdx=getCase(a);

  // Altitude visibility
  altGroup.attr({opacity:showAlt?1:0});

  // Draw arc (portion near base)
  var arcR=aPx;
  // Arc from angle pointing down-left to down-right
  var arcStart=-Math.PI*0.85;
  var arcEnd=-Math.PI*0.15;
  var arcPts=[];
  for(var i=0;i<=40;i++){
    var t=arcStart+(arcEnd-arcStart)*i/40;
    var ax2=lgx+arcR*Math.cos(t);
    var ay2=lgy-arcR*Math.sin(t);
    if(ay2<=lay+5) arcPts.push([ax2,ay2]);
  }
  if(arcPts.length>1){
    var d='M'+arcPts[0][0]+','+arcPts[0][1];
    for(var i=1;i<arcPts.length;i++) d+='L'+arcPts[i][0]+','+arcPts[i][1];
    arcPath.attr({d:d});
  } else {
    arcPath.attr({d:''});
  }

  // Intersections
  var disc=a*a-H_ALT*H_ALT;
  if(disc>=0){
    var sq=Math.sqrt(disc)*liveScale;
    var ix1=lgx-sq, ix2=lgx+sq;

    if(caseIdx===1){
      // Right triangle: one point at foot
      dot1.attr({cx:lgx,cy:lay,opacity:1});
      dot2.attr({opacity:0});
      sideALine.attr({x1:lgx,y1:lgy,x2:lgx,y2:lay});
      sideALabel.attr({x:lgx+16,y:(lgy+lay)/2});
      betaLabel.attr({x:lgx+10,y:lay+18,opacity:1});
      // Right angle marker
      drawRightAngleLive(lgx,lay);
    } else if(caseIdx===2){
      // Two triangles
      dot1.attr({cx:ix1,cy:lay,opacity:1});
      dot2.attr({cx:ix2,cy:lay,opacity:1});
      sideALine.attr({x1:lgx,y1:lgy,x2:ix2,y2:lay});
      sideALabel.attr({x:(lgx+ix2)/2+14,y:(lgy+lay)/2});
      betaLabel.attr({x:ix2+12,y:lay+18,opacity:1});
      clearRightAngleLive();
    } else {
      // One triangle (a>=b)
      dot1.attr({opacity:0});
      dot2.attr({cx:ix2,cy:lay,opacity:1});
      sideALine.attr({x1:lgx,y1:lgy,x2:ix2,y2:lay});
      sideALabel.attr({x:(lgx+ix2)/2+14,y:(lgy+lay)/2});
      betaLabel.attr({x:ix2+12,y:lay+18,opacity:1});
      clearRightAngleLive();
    }
  } else {
    // No triangle
    dot1.attr({opacity:0});
    dot2.attr({opacity:0});
    // Show a hanging down from γ
    var aEndY=lgy+aPx;
    sideALine.attr({x1:lgx,y1:lgy,x2:lgx,y2:Math.min(aEndY,lay-5)});
    sideALabel.attr({x:lgx+16,y:(lgy+Math.min(aEndY,lay-5))/2});
    betaLabel.attr({opacity:0});
    clearRightAngleLive();
  }

  // Case text
  var caseStr=caseNames[caseIdx];
  var ineqStr='';
  if(caseIdx===0) ineqStr='a < h  ('+a.toFixed(1)+' < '+H_ALT.toFixed(1)+')';
  else if(caseIdx===1) ineqStr='a = h  ('+a.toFixed(1)+' = '+H_ALT.toFixed(1)+')';
  else if(caseIdx===2) ineqStr='h < a < b  ('+H_ALT.toFixed(1)+' < '+a.toFixed(1)+' < '+B+')';
  else ineqStr='a ≥ b  ('+a.toFixed(1)+' ≥ '+B+')';

  caseText.attr({text:caseStr});
  ineqText.attr({text:ineqStr});

  // Highlight matching panel
  for(var i=0;i<4;i++){
    panelHighlights[i].attr({opacity:i===caseIdx?1:0});
  }
}

var rightAngleLive=null;
function drawRightAngleLive(x,y){
  clearRightAngleLive();
  rightAngleLive=liveG.polyline((x-12)+','+y+' '+(x-12)+','+(y-12)+' '+x+','+(y-12)).fill('none').stroke({color:colBlue,width:1.5});
}
function clearRightAngleLive(){
  if(rightAngleLive){rightAngleLive.remove();rightAngleLive=null;}
}

// ── Controls ─
window.update_sideA=function(v){
  currentA=v;
  updateLive();
};

window.toggle_showAltitude=function(on){
  showAlt=on;
  updateLive();
};

window.trigger_caseStep=function(){
  currentCaseIdx=(currentCaseIdx+1)%4;
  var targets=[4,5,7,11];
  currentA=targets[currentCaseIdx];
  document.getElementById('sideAInput').value=currentA;
  document.getElementById('sideAVal').value=currentA;
  updateLive();
};

